// Draw a 32x32 mini weather icon at (x,y).
template<typename TDisplay>
void drawMiniWeatherIcon(TDisplay& display, const uint8_t* bmp, int16_t x, int16_t y) {
  static const uint16_t COLORS[] = {
    GxEPD_WHITE, GxEPD_BLACK, GxEPD_RED, GxEPD_YELLOW, GxEPD_GREEN, GxEPD_BLUE
  };
  int idx=0;
  for(int16_t row=0;row<32;row++){
    for(int16_t col=0;col<32;col+=2){
      uint8_t b=pgm_read_byte(&bmp[idx++]);
      uint8_t hi=(b>>4)&0xF, lo=b&0xF;
      if(hi<6) display.drawPixel(x+col,  y+row,COLORS[hi]);
      if(lo<6) display.drawPixel(x+col+1,y+row,COLORS[lo]);
    }
  }
}

inline const uint8_t* miniWeatherIcon(const String& condition) {
  if (condition == "Sunny")              return mi_sunny;
  if (condition == "Clear Night")        return mi_night;
  if (condition == "Partly Cloudy")      return mi_partly_cloudy;
  if (condition == "Partly Cloudy Night")return mi_night_partly_cloudy;
  if (condition == "Cloudy")             return mi_cloudy;
  if (condition == "Rainy")              return mi_rainy;
  if (condition == "Pouring")            return mi_pouring;
  if (condition == "Thunderstorms")      return mi_lightning_rainy;
  if (condition == "Snowy")              return mi_snowy;
  if (condition == "Sleet")              return mi_snowy_rainy;
  if (condition == "Fog")                return mi_fog;
  if (condition == "Windy")              return mi_windy;
  if (condition == "Hail")               return mi_snowy;
  if (condition == "Lightning")          return mi_lightning_rainy;
  if (condition == "Exceptional")        return mi_cloudy;
  return mi_cloudy;
}